BEGIN TRANSACTION;
CREATE TABLE contract_spend_comparison (
    orgnr          TEXT,
    virksomhet     TEXT,
    year           INTEGER,
    contract_sum   REAL,
    contract_count INTEGER,
    spend_sum      REAL,
    deviation      REAL,     -- (contract_sum - spend_sum) / spend_sum
    match_method   TEXT,     -- 'orgnr' | 'navn'
    flagged        INTEGER,
    PRIMARY KEY (orgnr, year)
);
CREATE TABLE doffin_contract_years (
    contract_id     TEXT,
    buyer_orgnr     TEXT,
    year            INTEGER,
    share           REAL,     -- andel av kontraktsperioden som faller i året (0-1)
    value_share     REAL,     -- value * share
    period_source   TEXT,     -- 'datoer' | 'varighet' | 'tekst' | 'standard'
    PRIMARY KEY (contract_id, year)
);
CREATE TABLE doffin_contracts (
    id               TEXT PRIMARY KEY,
    buyer_orgnr      TEXT,
    buyer_name       TEXT,
    title            TEXT,
    value            REAL,
    year             INTEGER,
    url              TEXT,
    currency         TEXT,
    value_type       TEXT,
    publication_date TEXT,
    fetched_at       TEXT DEFAULT CURRENT_TIMESTAMP
, is_framework INTEGER, start_date TEXT, end_date TEXT, duration_months REAL, duration_source TEXT);
CREATE TABLE doffin_coverage (
    orgnr        TEXT,
    year         INTEGER,
    virksomhet   TEXT,
    coverage     REAL,     -- contract_sum / spend_sum
    peer_group   TEXT,     -- størrelsesgruppe etter kjøp
    peer_count   INTEGER,
    peer_median  REAL,     -- gruppens mediandekning
    z            REAL,     -- robust z-verdi på log10(dekning)
    flagged      INTEGER,
    PRIMARY KEY (orgnr, year)
);
CREATE TABLE doffin_winners (
    contract_id  TEXT,
    position     INTEGER,  -- rekkefølgen i kunngjøringen
    name         TEXT,
    orgnr        TEXT,     -- NULL når kunngjøringen bare har navn
    PRIMARY KEY (contract_id, position)
);
CREATE TABLE statsregnskap (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    year        INTEGER,
    orgnr       TEXT,
    virksomhet  TEXT,
    artskonto   TEXT,
    amount      REAL,
    source_file TEXT
);
DELETE FROM "sqlite_sequence";
COMMIT;
